#!/usr/bin/env node
// Render one share-card HTML per locale into scripts/share/, for
// scripts/make-share-images.sh to screenshot at 1200x630.

import { mkdir, writeFile, readFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { e } from "./template.mjs";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const LOCALES = ["en", "pt-BR", "es-419"];

const card = (t) => `<!doctype html>
<!-- Generated by scripts/build-share-cards.mjs. Rendered in a browser so the
     wordmark is set in the real Inter Tight, not in a rasteriser's substitute. -->
<html lang="${t.htmlLang}">
  <head>
    <meta charset="utf-8" />
    <link rel="stylesheet" href="/src/styles/tokens.css" />
    <link rel="stylesheet" href="/src/styles/fonts.css" />
    <style>
      html, body { margin: 0; }
      body {
        width: 1200px;
        height: 630px;
        display: flex;
        flex-direction: column;
        justify-content: center;
        gap: 32px;
        padding: 96px;
        box-sizing: border-box;
        background: var(--tl-paper);
        color: var(--tl-ink);
        font-family: var(--tl-font-body);
      }
      h1 {
        margin: 0;
        max-width: 22ch;
        font-family: var(--tl-font-display);
        font-size: 56px;
        font-weight: 600;
        line-height: 1.05;
        letter-spacing: -0.02em;
      }
      p {
        margin: 0;
        color: var(--tl-muted);
        font-family: var(--tl-font-mono);
        font-size: 20px;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }
    </style>
  </head>
  <body>
    <img src="/brand/logo/lockup-horizontal.svg" width="380" height="64" alt="" />
    <h1>${e(t.meta.shareLine)}</h1>
    <p>${e(t.meta.shareSub)}</p>
  </body>
</html>
`;

await mkdir(join(root, "scripts", "share"), { recursive: true });

for (const locale of LOCALES) {
  const t = JSON.parse(await readFile(join(root, "content", `${locale}.json`), "utf8"));
  const target = join(root, "scripts", "share", `${locale}.html`);
  await writeFile(target, card(t), "utf8");
  console.log(`Rendered share card ${locale}`);
}
